@KleisliIteration.sem_iter_proper
     : forall (M : Type -> Type) (MI : Measure.SemanticMeasure M),
       @Measure.SemanticMeasureCoreLaws M MI ->
       @Measure.SemanticMeasureBindLaws M MI ->
       forall MO : @Omega.SemanticOmega M MI,
       @Omega.SemanticMeasureOrderLaws M MI MO ->
       @Omega.SemanticOmegaLaws M MI MO ->
       @Omega.SemanticOmegaCofinalityLaws M MI MO ->
       forall (I A : Type) (K L : I -> M (I + A)%type),
       (forall i : I, @Measure.sem_eq M MI (I + A) (K i) (L i)) ->
       forall (i : I) (out out' : M A),
       @KleisliIteration.sem_iter M MI MO I A K i out ->
       @KleisliIteration.sem_iter M MI MO I A L i out' -> @Measure.sem_eq M MI A out out'

@ReturnIteration.ptree_iter_return_only_equiv
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF),
       @Measure.SemanticMeasureCoreLaws MF FI ->
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       forall (I A : Type) (step : I -> PTreeDefinition.ptree E MN (I + A)),
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       forall (front : I -> MF (UnifiedFrontier.stable_head E MN (I + A)))
         (K : I -> MF (I + A)%type),
       (forall i : I,
        @PTreeKernel.ptree_stable_hitting E MN MF FI MX FO (I + A)
          (@PTreeDefinition.observe E MN (I + A) (step i)) (front i)) ->
       (forall i : I,
        @Measure.sem_eq MF FI (UnifiedFrontier.stable_head E MN (I + A))
          (front i) (@ReturnIteration.iteration_return_front E MN MF FI I A K i)) ->
       forall (i : I) (out : MF A),
       @KleisliIteration.sem_iter MF FI FO I A K i out ->
       exists summary_out : MF (UnifiedFrontier.stable_head E MN A),
         @PTreeKernel.ptree_stable_hitting E MN MF FI MX FO A
           (@PTreeDefinition.observe E MN A (@PTreeDefinition.PTree.iter E MN A I step i))
           summary_out /\
         @Measure.sem_eq MF FI (UnifiedFrontier.stable_head E MN A) summary_out
           (@ReturnIteration.iteration_return_map E MN MF FI A out)

@Forward.denotes_unique
     : forall (S P : Type) (MN MF : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall FI : Measure.SemanticMeasure MF,
       @Measure.SemanticMeasureCoreLaws MF FI ->
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall MX : Mixed.MixedMeasure MN MF,
       @Mixed.MixedMeasureLaws MN MF NI FI MX ->
       forall FO : @Omega.SemanticOmega MF FI,
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       forall (coin : P -> MN bool) (c : Syntax.command S P) (K L : S -> MF S),
       @Forward.denotes S P MN MF FI MX FO coin c K ->
       @Forward.denotes S P MN MF FI MX FO coin c L -> @Forward.kernel_eq S MF FI K L

@Forward.denote_while_unfold
     : forall (S P : Type) (MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF),
       @Measure.SemanticMeasureCoreLaws MF FI ->
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI)
         (Ord : @Omega.SemanticMeasureOrderLaws MF FI FO),
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       forall (Select : @Omega.SemanticOmegaSelection MF FI FO) (coin : P -> MN bool),
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       forall (b : S -> bool) (c : Syntax.command S P) (s : S),
       @Measure.sem_eq MF FI S
         (@Forward.denote S P MN MF FI MX FO Ord Select coin (@Syntax.CWhile S P b c) s)
         (if b s
          then
           @Measure.sem_bind MF FI S S (@Forward.denote S P MN MF FI MX FO Ord Select coin c s)
             (@Forward.denote S P MN MF FI MX FO Ord Select coin (@Syntax.CWhile S P b c))
          else @Measure.sem_ret MF FI S s)

@Adequacy.pgcl_forward_correspondence
     : forall (MN MF E : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall FI : Measure.SemanticMeasure MF,
       @Measure.SemanticMeasureCoreLaws MF FI ->
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall MX : Mixed.MixedMeasure MN MF,
       @Mixed.MixedMeasureLaws MN MF NI FI MX ->
       forall FO : @Omega.SemanticOmega MF FI,
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Mixed.MixedMeasureOmegaLaws MN MF NI FI MX FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       forall (S P : Type) (coin : P -> MN bool) (c : Syntax.command S P)
         (K : @Forward.kernel S MF) (s : S) (out : MF (UnifiedFrontier.stable_head E MN S)),
       @Forward.denotes S P MN MF FI MX FO coin c K ->
       @PTreeKernel.ptree_stable_hitting E MN MF FI MX FO S
         (@PTreeDefinition.observe E MN S (@Interpretation.execute S P MN E coin c s)) out ->
       @Measure.sem_eq MF FI (UnifiedFrontier.stable_head E MN S) out
         (@ReturnIteration.iteration_return_map E MN MF FI S (K s))

@StateInterpretation.run_execute
     : forall (S P : Type) (MN MF E : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall (FI : Measure.SemanticMeasure MF) (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall MX : Mixed.MixedMeasure MN MF,
       @Mixed.MixedMeasureLaws MN MF NI FI MX ->
       forall FO : @Omega.SemanticOmega MF FI,
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Mixed.MixedMeasureOmegaLaws MN MF NI FI MX FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       @RelationalClosure.relational_mixed_bind MN MF NI FI MX ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (coin : P -> MN bool) (c : Syntax.command S P) (s : S),
       @PEutt.peutt E MN MF FI FC MX FO S S (@eq S) (@Interpretation.run S P MN E coin c s)
         (@Interpretation.execute S P MN E coin c s)

@FreeOmega.pgcl_run_denotes_iff
     : forall (S P : Type) (MN E : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       @AE.SemanticMeasureAELiftLaws MN NI ->
       @Coupling.SemanticMeasureCouplingAELaws MN NI ->
       @AE.SemanticMeasureCountableAELaws MN NI ->
       forall (NO : @Omega.SemanticOmega MN NI) (coin : P -> MN bool) (c : Syntax.command S P)
         (K : S -> Definition.FreeOmega MN S),
       @Forward.denotes S P MN (Definition.FreeOmega MN)
         (@Measure.FreeOmegaObservableSemanticMeasure MN NI NO)
         (@StructuralMeasure.FreeOmegaMixedMeasure MN)
         (@Measure.FreeOmegaObservableSemanticOmega MN NI NO) coin c K <->
       (forall s : S,
        @PTreeKernel.ptree_stable_hitting E MN (Definition.FreeOmega MN)
          (@Measure.FreeOmegaObservableSemanticMeasure MN NI NO)
          (@StructuralMeasure.FreeOmegaMixedMeasure MN)
          (@Measure.FreeOmegaObservableSemanticOmega MN NI NO) S
          (@PTreeDefinition.observe E MN S (@Interpretation.run S P MN E coin c s))
          (@ReturnIteration.iteration_return_map E MN (Definition.FreeOmega MN)
             (@Measure.FreeOmegaObservableSemanticMeasure MN NI NO) S (K s)))

@Algebra.cequiv_denotes
     : forall (S P : Type) (MN MF : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall FI : Measure.SemanticMeasure MF,
       @Measure.SemanticMeasureCoreLaws MF FI ->
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall MX : Mixed.MixedMeasure MN MF,
       @Mixed.MixedMeasureLaws MN MF NI FI MX ->
       forall (FO : @Omega.SemanticOmega MF FI) (Ord : @Omega.SemanticMeasureOrderLaws MF FI FO),
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       forall (Select : @Omega.SemanticOmegaSelection MF FI FO) (coin : P -> MN bool)
         (c d : Syntax.command S P),
       @Algebra.cequiv S P MN MF FI MX FO Ord Select coin c d <->
       (forall K : @Forward.kernel S MF,
        @Forward.denotes S P MN MF FI MX FO coin c K <->
        @Forward.denotes S P MN MF FI MX FO coin d K)

@Algebra.while_Proper
     : forall (S P : Type) (MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF),
       @Measure.SemanticMeasureCoreLaws MF FI ->
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI)
         (Ord : @Omega.SemanticMeasureOrderLaws MF FI FO),
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       forall (Select : @Omega.SemanticOmegaSelection MF FI FO) (coin : P -> MN bool)
         (b : S -> bool),
       @Morphisms.Proper (Syntax.command S P -> Syntax.command S P)
         (@Morphisms.respectful (Syntax.command S P) (Syntax.command S P)
            (@Algebra.cequiv S P MN MF FI MX FO Ord Select coin)
            (@Algebra.cequiv S P MN MF FI MX FO Ord Select coin)) (@Syntax.CWhile S P b)

@Algebra.seq_skip_r
     : forall (S P : Type) (MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI)
         (Ord : @Omega.SemanticMeasureOrderLaws MF FI FO)
         (Select : @Omega.SemanticOmegaSelection MF FI FO) (coin : P -> MN bool),
       (forall mu : MF S,
        @Measure.sem_eq MF FI S (@Measure.sem_bind MF FI S S mu (@Measure.sem_ret MF FI S)) mu) ->
       forall c : Syntax.command S P,
       @Algebra.cequiv S P MN MF FI MX FO Ord Select coin (@Syntax.CSeq S P c (@Syntax.CSkip S P))
         c

@Algebra.seq_assoc
     : forall (S P : Type) (MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI)
         (Ord : @Omega.SemanticMeasureOrderLaws MF FI FO)
         (Select : @Omega.SemanticOmegaSelection MF FI FO) (coin : P -> MN bool)
         (c d e : Syntax.command S P),
       @Algebra.cequiv S P MN MF FI MX FO Ord Select coin
         (@Syntax.CSeq S P (@Syntax.CSeq S P c d) e) (@Syntax.CSeq S P c (@Syntax.CSeq S P d e))

@Algebra.choice_seq
     : forall (S P : Type) (MN MF : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall FI : Measure.SemanticMeasure MF,
       @Measure.SemanticMeasureCoreLaws MF FI ->
       forall MX : Mixed.MixedMeasure MN MF,
       @Mixed.MixedMeasureLaws MN MF NI FI MX ->
       forall (FO : @Omega.SemanticOmega MF FI) (Ord : @Omega.SemanticMeasureOrderLaws MF FI FO)
         (Select : @Omega.SemanticOmegaSelection MF FI FO) (coin : P -> MN bool)
         (p : P) (c d e : Syntax.command S P),
       @Algebra.cequiv S P MN MF FI MX FO Ord Select coin
         (@Syntax.CSeq S P (@Syntax.CChoice S P p c d) e)
         (@Syntax.CChoice S P p (@Syntax.CSeq S P c e) (@Syntax.CSeq S P d e))

@Algebra.while_skip_diverge
